select * from booknest.`post`


        and category_id = #{categoryId}


        and id in (select post_id from booknest.`post_tag` where tag_id = #{tagId})


        and audit_status = #{auditStatus}


        and status = #{status}


order by publish_time desc, create_time desc

mapper.update:
update booknest.`post`
title = #{title}, summary = #{summary}, content_url = #{contentUrl}, cover_image = #{coverImage}, category_id = #{categoryId}, book_id = #{bookId}, status = #{status}, audit_status = #{auditStatus}, audit_reason = #{auditReason}, audit_time = #{auditTime}, is_top = #{isTop}, publish_time = #{publishTime}, update_time = #{updateTime},
where id = #{id}
